contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _lockTime, uint _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_amount)); require(_amount <= 1000000000000000000000000000000);
        require(_amount > 0);
        require(address(this).balance >= _amount);

        uint beforeContractBalance = address(c).balance;

        c.Put{value: _amount}(_lockTime); if (__ESBMC_reverted()) return;

        uint afterContractBalance = address(c).balance;

        assert(afterContractBalance == beforeContractBalance + _amount);
    }

    receive() external payable {}
}

