// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _lockTime, uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_amount > 0);
        vm.assume(address(this).balance >= _amount);
        uint beforeContractBalance = address(c).balance;
        try c.Put{value: _amount}(_lockTime) {} catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(afterContractBalance == beforeContractBalance + _amount);
    }

    function testFuzz_run(uint256 _lockTime, uint256 _amount) public {
        _run(_lockTime, _amount);
    }

    receive() external payable {}
}
